contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(address target, uint256 freezeAmount, uint256 transferAmount) public {
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 ownerBalanceBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 targetBalanceBefore = c.balanceOf(target); if (__ESBMC_reverted()) return;

        c.freezeAccount(target, true); if (__ESBMC_reverted()) return;

        bool reverted;
        c.transfer(target, transferAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            reverted &&
            c.totalSupply() == supplyBefore &&
            c.balanceOf(address(this)) == ownerBalanceBefore &&
            c.balanceOf(target) == targetBalanceBefore &&
            c.frozenAccount(target) == true
        );
    }
}

